import type { ControlUiSkin } from "@/components/control-ui/skin";

// Flat needs no slot overrides: its complete theme owns squared corners, zero shadows, and one neutral plane on the stock motion tempo.
export const skin: ControlUiSkin = { id: "flat" };

[data-skin="flat"][data-skin] {
  --font-sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, monospace;

  --primary: oklch(0.2046 0 0); /* neutral-900 */
  --primary-foreground: oklch(0.9851 0 0); /* neutral-50 */
  --foreground: oklch(0.1448 0 0); /* neutral-950 */
  --secondary-foreground: oklch(0.1448 0 0);
  --accent-foreground: oklch(0.1448 0 0);

  --background: oklch(1 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.1448 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.1448 0 0);
  --canvas: oklch(1 0 0); /* flat = page == surfaces, no floating "paper" level */

  /* structural reset */
  --radius: 0px; /* squares every control + surface (the radius scale is multiplied from --radius) */
  --shadow-size: 0; /* zero elevation — flattens the token-gated --shadow-* scale */
  --scroll-fade-size: 0px; /* hard edges */
  --backdrop-blur-popover: 0px;
  --backdrop-blur-overlay: 0px;

  /* these CANNOT be 0 (would break rendering) — kept at real values */
  --control-h: 36px; /* 0 = buttons/inputs collapse to invisible */
  --popover-opacity: 1; /* 0 = transparent popovers */
  --overlay-opacity: 0.2; /* keeps the dialog backdrop dim */
  --padding-x: 16px; /* 0 = content glued to surface edges */
  --padding-y: 10px;

  --muted: oklch(0.9425 0 0);
  --muted-foreground: oklch(0.52 0 0);
  --secondary: oklch(0.9425 0 0);
  --accent: oklch(0.9295 0 0);
  --destructive: oklch(0.568 0.1961 32);
  --destructive-foreground: oklch(0.9852 0.0058 85);
  --border: oklch(0.8851 0 0 / var(--ring-opacity));
  --input: oklch(0.8851 0 0);
  --ring: oklch(0.6903 0 0);
  --focus-ring: oklch(0.5 0 0);
  --text-label: 0.75rem;
  --radius-control: calc(var(--radius) * 2);
  --radius-field: calc(var(--radius) * 2.2);
  --radius-panel: calc(var(--radius) * 2.6);
  --radius-scene: calc(var(--radius) * 2.8);
  --radius-popup-item: calc(var(--radius-control) * 0.6);
  --shadow-color: oklch(0.2986 0 0);
  --shadow-opacity: 1;
  --duration-fast: 150ms;
  --duration-base: 200ms;
  --duration-slow: 300ms;
  --ease-standard: cubic-bezier(0.2, 0, 0, 1);
  --ease-emphasized: cubic-bezier(0.16, 1, 0.3, 1);
  --popover-padding: 0.25rem;
}

.dark[data-skin="flat"][data-skin],
:where(.dark) [data-skin="flat"][data-skin] {
  --primary: oklch(0.9851 0 0);
  --primary-foreground: oklch(0.2046 0 0);
  --foreground: oklch(0.9851 0 0);
  --card-foreground: oklch(0.9851 0 0);
  --popover-foreground: oklch(0.9851 0 0);
  --secondary-foreground: oklch(0.9851 0 0);
  --accent-foreground: oklch(0.9851 0 0);
  --background: oklch(0.1448 0 0);
  --card: oklch(0.2046 0 0);
  --popover: oklch(0.2046 0 0);
  --canvas: oklch(0.1448 0 0);

  --muted: oklch(0.2668 0 0);
  --muted-foreground: oklch(0.7405 0 0);
  --secondary: oklch(0.2668 0 0);
  --accent: oklch(0.2864 0 0);
  --destructive: oklch(0.551 0.1799 32);
  --destructive-foreground: oklch(0.9645 0.008 84);
  --border: oklch(0.3082 0 0 / var(--ring-opacity));
  --input: oklch(0.3082 0 0);
  --ring: oklch(0.5521 0 0);
  --focus-ring: oklch(0.66 0 0);
  --shadow-color: oklch(0 0 0);
}
